res = [-1]*n
st = []  # indices, decreasing values
for i in range(n-1, -1, -1):
    while st and a[st[-1]] <= a[i]: st.pop()
    if st: res[i] = a[st[-1]]
    st.append(i)

def solve(state):
    if is_complete(state): record(state); return
    for choice in choices(state):
        if valid(choice):
            apply(choice)      # choose
            solve(state)       # explore
            undo(choice)       # un-choose

